79: function saveLook(){const name=`${labelFor('palette',state.palette).name} ${labelFor('look',state.look).name}`;saved.unshift({name,look:labelFor('look',state.look).name,bottom:labelFor('bottom',state.bottom).name,extra:labelFor('extra',state.extra).name,palette:labelFor('palette',state.palette).name});saved=saved.slice(0,20);localStorage.setItem('muse-saves',JSON.stringify(saved));renderHeader();showToast('Tucked into your little wardrobe ♡');}
80: document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){active=tab.dataset.tab;renderTabs();renderOptions();return;}const choice=e.target.closest('[data-choice]');if(choice){choose(active,choice.dataset.choice);return;}});
