input.oldString:
prepareBtn.addEventListener('click', () => {
  if (prepareBtn.disabled || !selectedFile) return;
  currentBrief = `IMAGE EDITING BRIEF\n\nSelected image: ${selectedFile.name}\n\nRequested edit:\n${promptInput.value.trim()}\n\nPreserve the subject's identity and any details not specifically requested to change. Use only with the depicted adult's permission.`;
  briefText.textContent = currentBrief;
  resultPanel.hidden = false;
  resultPanel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
});

document.getElementById('copyBtn').addEventListener('click', async () => {
  if (!currentBrief) return;
  try {
    await navigator.clipboard.writeText(currentBrief);
    showToast('Brief copied to clipboard.');
  } catch (error) {
    const selection = window.getSelection();
    const range = document.createRange();
    range.selectNodeContents(briefText);
    selection.removeAllRanges();
    selection.addRange(range);
    showToast('Select the highlighted brief and copy it.');
  }
});
document.getElementById('downloadBtn').addEventListener('click', () => {
  if (!currentBrief) return;
  const url = URL.createObjectURL(new Blob([currentBrief], { type: 'text/plain;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = 'muse-edit-brief.txt';
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
  showToast('Brief downloaded.');
});

window.addEventListener('beforeunload', () => {
  if (previewUrl) URL.revokeObjectURL(previewUrl);
});

input.newString:
prepareBtn.addEventListener('click', async () => {
  if (prepareBtn.disabled || !selectedFile) return;
  prepareBtn.disabled = true;
  prepareBtn.textContent = 'Generating...';
  resultHeading.textContent = 'Generating your edited image…';
  resultMessage.textContent = 'Uploading your photo and prompt to the image model.';
  resultImageWrap.hidden = true;
  resultActions.hidden = true;
  resultPanel.hidden = false;
  currentPrompt = promptInput.value.trim();

  const form = new FormData();
  form.append('image', selectedFile);
  form.append('prompt', currentPrompt);
  form.append('adultConsent', String(consentCheck.checked));

  try {
    const response = await fetch('/api/edit', {
      method: 'POST',
      body: form,
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(data.error || 'The edit could not be generated.');
    }
    if (!data.image) throw new Error('The service did not return an edited image.');
    if (resultUrl) URL.revokeObjectURL(resultUrl);
    resultUrl = data.image;
    resultImage.src = resultUrl;
    resultImageWrap.hidden = false;
    saveImageBtn.href = resultUrl;
    resultHeading.textContent = 'Edited image ready';
    resultMessage.textContent = 'This generated result matches your prompt. You can save it or copy the prompt below.';
    resultActions.hidden = false;
    resultPanel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } catch (error) {
    resultHeading.textContent = 'Image generation failed';
    resultMessage.textContent = error.message || 'Something went wrong while generating the image.';
    resultImageWrap.hidden = true;
    resultActions.hidden = true;
    showToast(error.message || 'Image generation failed.');
  } finally {
    prepareBtn.disabled = !(selectedFile && promptInput.value.trim() && consentCheck.checked);
    prepareBtn.innerHTML = '<span>✦</span> Generate edited preview <span class="arrow">→</span>';
  }
});

document.getElementById('copyBtn').addEventListener('click', async () => {
  if (!currentPrompt) return;
  try {
    await navigator.clipboard.writeText(currentPrompt);
    showToast('Prompt copied to clipboard.');
  } catch (error) {
    showToast('Copy failed. Please copy the prompt manually.');
  }
});

window.addEventListener('beforeunload', () => {
  if (previewUrl) URL.revokeObjectURL(previewUrl);
  if (resultUrl) URL.revokeObjectURL(resultUrl);
});

