100:   }
101: 
102:   function openPicker() {
103:     fileInput.click();
104:   }
105: 
106:   function useFile(file) {
107:     if (!file) return;
108:     const supportedTypes = ['image/jpeg', 'image/png', 'image/webp'];
109:     if (!supportedTypes.includes(file.type)) {
110:       showToast('Choose a JPG, PNG, or WEBP image.');
111:       fileInput.value = '';
