113:     }
114:     if (file.size > 15 * 1024 * 1024) {
115:       showToast('That image is larger than 15 MB. Choose a smaller file.');
116:       fileInput.value = '';
117:       return;
118:     }
119:     if (previewUrl) URL.revokeObjectURL(previewUrl);
120:     selectedFile = file;
