131:   dropZone.addEventListener('click', event => {
132:     if (event.target.closest('.change-photo')) return;
133:     openPicker();
134:   });
135:   dropZone.addEventListener('keydown', event => {
136:     if (event.target === dropZone && (event.key === 'Enter' || event.key === ' ')) {
137:       event.preventDefault();
138:       openPicker();
139:     }
140:   });
141:   changePhoto.addEventListener('click', event => {
142:     event.stopPropagation();
143:     openPicker();
144:   });
145:   fileInput.addEventListener('change', () => {
146:     if (fileInput.files.length) useFile(fileInput.files[0]);
147:   });
148:   ['dragenter', 'dragover'].forEach(type => dropZone.addEventListener(type, event => {
149:     event.preventDefault();
150:     dropZone.classList.add('dragging');
151:   }));
152:   ['dragleave', 'drop'].forEach(type => dropZone.addEventListener(type, event => {
153:     event.preventDefault();
154:     dropZone.classList.remove('dragging');
155:   }));
156:   dropZone.addEventListener('drop', event => {
157:     const file = event.dataTransfer.files[0];
