159:   });
160: 
161:   promptInput.addEventListener('input', () => {
162:     resultPanel.hidden = true;
163:     refreshForm();
164:   });
165:   consentCheck.addEventListener('change', refreshForm);
166:   document.getElementById('examples').addEventListener('click', event => {
167:     const example = event.target.closest('[data-prompt]');
168:     if (!example) return;
169:     promptInput.value = example.dataset.prompt;
170:     promptInput.dispatchEvent(new Event('input', { bubbles: true }));
171:     promptInput.focus();
172:   });
173: 
174:   prepareBtn.addEventListener('click', async () => {
175:     if (prepareBtn.disabled || !selectedFile) return;
176:     prepareBtn.disabled = true;
177:     prepareBtn.textContent = 'Generating...';
178:     resultHeading.textContent = 'Generating your edited image…';
179:     resultMessage.textContent = 'Uploading your photo and prompt to the image model.';
180:     resultImageWrap.hidden = true;
181:     resultActions.hidden = true;
182:     resultPanel.hidden = false;
183:     currentPrompt = promptInput.value.trim();
184: 
185:     const form = new FormData();
186:     form.append('image', selectedFile);
187:     form.append('prompt', currentPrompt);
188:     form.append('adultConsent', String(consentCheck.checked));
189: 
190:     try {
191:       const response = await fetch('/api/edit', {
192:         method: 'POST',
193:         body: form,
194:       });
195:       const data = await response.json().catch(() => ({}));
196:       if (!response.ok) {
197:         throw new Error(data.error || 'The edit could not be generated.');
198:       }
199:       if (!data.image) throw new Error('The service did not return an edited image.');
200:       if (resultUrl) URL.revokeObjectURL(resultUrl);
201:       resultUrl = data.image;
202:       resultImage.src = resultUrl;
203:       resultImageWrap.hidden = false;
204:       saveImageBtn.href = resultUrl;
205:       resultHeading.textContent = 'Edited image ready';
206:       resultMessage.textContent = 'This generated result matches your prompt. You can save it or copy the prompt below.';
207:       resultActions.hidden = false;
208:       resultPanel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
209:     } catch (error) {
210:       resultHeading.textContent = 'Image generation failed';
211:       resultMessage.textContent = error.message || 'Something went wrong while generating the image.';
212:       resultImageWrap.hidden = true;
213:       resultActions.hidden = true;
214:       showToast(error.message || 'Image generation failed.');
215:     } finally {
216:       prepareBtn.disabled = !(selectedFile && promptInput.value.trim() && consentCheck.checked);
217:       prepareBtn.innerHTML = '<span>✦</span> Generate edited preview <span class="arrow">→</span>';
218:     }
219:   });
220: 
221:   document.getElementById('copyBtn').addEventListener('click', async () => {
222:     if (!currentPrompt) return;
223:     try {
224:       await navigator.clipboard.writeText(currentPrompt);
225:       showToast('Prompt copied to clipboard.');
226:     } catch (error) {
227:       showToast('Copy failed. Please copy the prompt manually.');
228:     }
229:   });
230: 
231:   window.addEventListener('beforeunload', () => {
232:     if (previewUrl) URL.revokeObjectURL(previewUrl);
233:     if (resultUrl) URL.revokeObjectURL(resultUrl);
234:   });
235:   refreshForm();
236: })();
237: </script>
238: </body>
